/**
 * Motion coherence filter: compare each feature's motion vector against the median.
 * If the centerFeature's motion is an outlier (likely caused by shadow/illumination change),
 * revert it to the previous frame's position so the tracked object stays stable.
 */
private applyMotionCoherenceFilter(trackedFeatures: Feature[]): void {
  this.motionCoherenceRejected = false;

  if (!this.centerFeature || trackedFeatures.length < 3) return;

  // Build motion vectors for features that existed in the previous frame
  const motions: { id: number; dx: number; dy: number }[] = [];
  for (const feature of trackedFeatures) {
    const previous = this.prevFeatures.find((p) => p.id === feature.id);
    if (previous) {
      motions.push({
        id: feature.id,
        dx: feature.x - previous.x,
        dy: feature.y - previous.y,
      });
    }
  }

  if (motions.length < 3) return;

  const centerMotion = motions.find((m) => m.id === this.centerFeature!.id);
  if (!centerMotion) return;

  // Compute median dx/dy
  const sortedDx = motions.map((m) => m.dx).sort((a, b) => a - b);
  const sortedDy = motions.map((m) => m.dy).sort((a, b) => a - b);
  const mid = Math.floor(sortedDx.length / 2);
  const medianDx =
    sortedDx.length % 2 === 0
      ? (sortedDx[mid - 1] + sortedDx[mid]) / 2
      : sortedDx[mid];
  const medianDy =
    sortedDy.length % 2 === 0
      ? (sortedDy[mid - 1] + sortedDy[mid]) / 2
      : sortedDy[mid];

  // Compute MAD (Median Absolute Deviation) for robust outlier detection
  const deviations = motions.map((m) =>
    Math.sqrt((m.dx - medianDx) ** 2 + (m.dy - medianDy) ** 2),
  );
  const sortedDeviations = [...deviations].sort((a, b) => a - b);
  const madMid = Math.floor(sortedDeviations.length / 2);
  const mad =
    sortedDeviations.length % 2 === 0
      ? (sortedDeviations[madMid - 1] + sortedDeviations[madMid]) / 2
      : sortedDeviations[madMid];

  // Deviation of centerFeature from median
  const centerDeviation = Math.sqrt(
    (centerMotion.dx - medianDx) ** 2 + (centerMotion.dy - medianDy) ** 2,
  );

  // Reject if centerFeature deviates beyond threshold * MAD (with a minimum MAD floor)
  const effectiveMad = Math.max(mad, 0.3);
  if (centerDeviation > this.motionCoherenceThreshold * effectiveMad) {
    // Revert centerFeature to previous position
    const previous = this.prevFeatures.find(
      (p) => p.id === this.centerFeature!.id,
    );
    if (previous) {
      const index = trackedFeatures.findIndex(
        (f) => f.id === this.centerFeature!.id,
      );
      if (index !== -1) {
        trackedFeatures[index] = {
          ...trackedFeatures[index],
          x: previous.x,
          y: previous.y,
        };
      }
    }
    this.motionCoherenceRejected = true;
  }
}

