      (origX - backX) * (origX - backX) + (origY - backY) * (origY - backY)
    );

    if (fbError > this.forwardBackwardThreshold) continue;

    const newX = nextPoints.data32F[i * 2];
    const newY = nextPoints.data32F[i * 2 + 1];

